CREATE TABLE IF NOT EXISTS vaults (id TEXT PRIMARY KEY, rev INTEGER NOT NULL, data TEXT NOT NULL, iv TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS history (id TEXT NOT NULL, rev INTEGER NOT NULL, data TEXT NOT NULL, iv TEXT NOT NULL, updated TEXT NOT NULL, PRIMARY KEY(id,rev));
CREATE TABLE IF NOT EXISTS images (workspace TEXT NOT NULL, id TEXT NOT NULL, data TEXT NOT NULL, iv TEXT NOT NULL, created TEXT NOT NULL, PRIMARY KEY(workspace,id));
